window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-fffa62ee09fd2e4f"]={"versions": [{"id": "FIG-fffa62ee09fd2e4f", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing Diagram) im Kontext des AUTOSAR Communication Stack, speziell des LIN Interface (LinIf) und dessen Zusammenwirken mit dem zugrundeliegenden LIN Driver (Lin). Das Diagramm stellt das zeitliche Raster und die zyklische Ausführung von <code>LinIf_MainFunction</code> in Relation zur Übertragung eines LIN-Frames auf dem Bus dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>LinIf (LIN Interface)</strong>: Aufrufende BSW-Schicht, führt zyklisch <code>LinIf_MainFunction</code> aus.\n</li><li><strong>Lin (LIN Driver)</strong>: Treiberebene mit den aufgerufenen C-Schnittstellen:\n<ul class=\"fig-list\"><li><code>Lin_SendHeader</code>: Initiiert das Senden des LIN-Headers (Synch Break, Synch Field, Protected Identifier).\n</li><li><code>Lin_SendResponse</code>: Bereitstellung bzw. Anstoßen des Sendens der Response (Datenbytes und Checksum).\n</li><li><code>Lin_GetStatus</code>: Polling-Schnittstelle zur Abfrage des aktuellen Übertragungsstatus des LIN-Treibers bzw. der Response.\n</li></ul>\n</li><li><strong>LIN-Frame</strong>: Unterteilt in zwei sequenzielle Segmente auf dem Bus:\n<ul class=\"fig-list\"><li><code>Header</code>\n</li><li><code>Response</code>\n</li></ul>\n</li><li><strong>Zeitachse</strong>: Diskrete Zeitachse, beschriftet mit <code>ticks</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Erster Aufruf (<code>First call of LinIf_MainFunction</code>)</strong>:\n<ul class=\"fig-list\"><li>Die periodische Task ruft <code>LinIf_MainFunction</code> auf.\n</li><li>Zu Beginn der Frame-Übertragung ruft das LinIf synchron <code>Lin_SendHeader</code> und <code>Lin_SendResponse</code> am LIN-Treiber auf.\n</li><li>Auf dem Bus startet daraufhin die Übertragung des <code>Header</code>, gefolgt von der <code>Response</code>.\n</li></ul>\n</li><li><strong>Zweiter Aufruf (<code>Second call of LinIf_MainFunction</code>)</strong>:\n<ul class=\"fig-list\"><li>Im nachfolgenden Tick erfolgt der zweite Aufruf von <code>LinIf_MainFunction</code>.\n</li><li>Da die Übertragung der <code>Response</code> auf dem Bus noch aktiv ist, führt <code>LinIf_MainFunction</code> keine Aktion aus (<code>no action</code>).\n</li></ul>\n</li><li><strong>Dritter Aufruf (<code>Third call of LinIf_MainFunction</code>)</strong>:\n<ul class=\"fig-list\"><li>Nach Abschluss der Response-Übertragung auf dem Bus erfolgt der dritte Aufruf von <code>LinIf_MainFunction</code>.\n</li><li>Das LinIf ruft <code>Lin_GetStatus</code> auf, um den Status der übertragenen Response vom LIN-Treiber abzufragen und das Frame-Timing abzuschließen.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Verdeutlicht das polling-basierte Design des LIN-Interface-Schedulings bei Transmit-Frames.\n</li><li><code>LinIf_MainFunction</code> muss mit einer Periodendauer (Tick-Rate) aufgerufen werden, die feingranular genug ist, um das Frame-Timing und die Statusabfragen abzubilden.\n</li><li>Entwickler müssen beachten, dass das LIN-Interface bei Übertragungen, die sich über mehrere Ticks erstrecken, Zwischenaufrufe ohne Bus-/Treiberaktionen durchläuft, bis das erwartete Übertragungsende erreicht ist und der Status via <code>Lin_GetStatus</code> verifiziert wird.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-7e78571c65300fe4", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing Diagram) im Kontext des AUTOSAR Communication Stack, speziell des LIN Interface (LinIf) und dessen Zusammenwirken mit dem zugrundeliegenden LIN Driver (Lin). Das Diagramm stellt das zeitliche Raster und die zyklische Ausführung von <code>LinIf_MainFunction</code> in Relation zur Übertragung eines LIN-Frames auf dem Bus dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>LinIf (LIN Interface)</strong>: Aufrufende BSW-Schicht, führt zyklisch <code>LinIf_MainFunction</code> aus.\n</li><li><strong>Lin (LIN Driver)</strong>: Treiberebene mit den aufgerufenen C-Schnittstellen:\n<ul class=\"fig-list\"><li><code>Lin_SendHeader</code>: Initiiert das Senden des LIN-Headers (Synch Break, Synch Field, Protected Identifier).\n</li><li><code>Lin_SendResponse</code>: Bereitstellung bzw. Anstoßen des Sendens der Response (Datenbytes und Checksum).\n</li><li><code>Lin_GetStatus</code>: Polling-Schnittstelle zur Abfrage des aktuellen Übertragungsstatus des LIN-Treibers bzw. der Response.\n</li></ul>\n</li><li><strong>LIN-Frame</strong>: Unterteilt in zwei sequenzielle Segmente auf dem Bus:\n<ul class=\"fig-list\"><li><code>Header</code>\n</li><li><code>Response</code>\n</li></ul>\n</li><li><strong>Zeitachse</strong>: Diskrete Zeitachse, beschriftet mit <code>ticks</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Erster Aufruf (<code>First call of LinIf_MainFunction</code>)</strong>:\n<ul class=\"fig-list\"><li>Die periodische Task ruft <code>LinIf_MainFunction</code> auf.\n</li><li>Zu Beginn der Frame-Übertragung ruft das LinIf synchron <code>Lin_SendHeader</code> und <code>Lin_SendResponse</code> am LIN-Treiber auf.\n</li><li>Auf dem Bus startet daraufhin die Übertragung des <code>Header</code>, gefolgt von der <code>Response</code>.\n</li></ul>\n</li><li><strong>Zweiter Aufruf (<code>Second call of LinIf_MainFunction</code>)</strong>:\n<ul class=\"fig-list\"><li>Im nachfolgenden Tick erfolgt der zweite Aufruf von <code>LinIf_MainFunction</code>.\n</li><li>Da die Übertragung der <code>Response</code> auf dem Bus noch aktiv ist, führt <code>LinIf_MainFunction</code> keine Aktion aus (<code>no action</code>).\n</li></ul>\n</li><li><strong>Dritter Aufruf (<code>Third call of LinIf_MainFunction</code>)</strong>:\n<ul class=\"fig-list\"><li>Nach Abschluss der Response-Übertragung auf dem Bus erfolgt der dritte Aufruf von <code>LinIf_MainFunction</code>.\n</li><li>Das LinIf ruft <code>Lin_GetStatus</code> auf, um den Status der übertragenen Response vom LIN-Treiber abzufragen und das Frame-Timing abzuschließen.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Verdeutlicht das polling-basierte Design des LIN-Interface-Schedulings bei Transmit-Frames.\n</li><li><code>LinIf_MainFunction</code> muss mit einer Periodendauer (Tick-Rate) aufgerufen werden, die feingranular genug ist, um das Frame-Timing und die Statusabfragen abzubilden.\n</li><li>Entwickler müssen beachten, dass das LIN-Interface bei Übertragungen, die sich über mehrere Ticks erstrecken, Zwischenaufrufe ohne Bus-/Treiberaktionen durchläuft, bis das erwartete Übertragungsende erreicht ist und der Status via <code>Lin_GetStatus</code> verifiziert wird.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-85747e80641fc41d", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitablaufdiagramm (Timing Diagram) im Kontext des AUTOSAR Communication Stack, speziell des LIN Interface (LinIf) und dessen Zusammenwirken mit dem zugrundeliegenden LIN Driver (Lin). Das Diagramm stellt das zeitliche Raster und die zyklische Ausführung von <code>LinIf_MainFunction</code> in Relation zur Übertragung eines LIN-Frames auf dem Bus dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>LinIf (LIN Interface)</strong>: Aufrufende BSW-Schicht, führt zyklisch <code>LinIf_MainFunction</code> aus.\n</li><li><strong>Lin (LIN Driver)</strong>: Treiberebene mit den aufgerufenen C-Schnittstellen:\n<ul class=\"fig-list\"><li><code>Lin_SendHeader</code>: Initiiert das Senden des LIN-Headers (Synch Break, Synch Field, Protected Identifier).\n</li><li><code>Lin_SendResponse</code>: Bereitstellung bzw. Anstoßen des Sendens der Response (Datenbytes und Checksum).\n</li><li><code>Lin_GetStatus</code>: Polling-Schnittstelle zur Abfrage des aktuellen Übertragungsstatus des LIN-Treibers bzw. der Response.\n</li></ul>\n</li><li><strong>LIN-Frame</strong>: Unterteilt in zwei sequenzielle Segmente auf dem Bus:\n<ul class=\"fig-list\"><li><code>Header</code>\n</li><li><code>Response</code>\n</li></ul>\n</li><li><strong>Zeitachse</strong>: Diskrete Zeitachse, beschriftet mit <code>ticks</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Erster Aufruf (<code>First call of LinIf_MainFunction</code>)</strong>:\n<ul class=\"fig-list\"><li>Die periodische Task ruft <code>LinIf_MainFunction</code> auf.\n</li><li>Zu Beginn der Frame-Übertragung ruft das LinIf synchron <code>Lin_SendHeader</code> und <code>Lin_SendResponse</code> am LIN-Treiber auf.\n</li><li>Auf dem Bus startet daraufhin die Übertragung des <code>Header</code>, gefolgt von der <code>Response</code>.\n</li></ul>\n</li><li><strong>Zweiter Aufruf (<code>Second call of LinIf_MainFunction</code>)</strong>:\n<ul class=\"fig-list\"><li>Im nachfolgenden Tick erfolgt der zweite Aufruf von <code>LinIf_MainFunction</code>.\n</li><li>Da die Übertragung der <code>Response</code> auf dem Bus noch aktiv ist, führt <code>LinIf_MainFunction</code> keine Aktion aus (<code>no action</code>).\n</li></ul>\n</li><li><strong>Dritter Aufruf (<code>Third call of LinIf_MainFunction</code>)</strong>:\n<ul class=\"fig-list\"><li>Nach Abschluss der Response-Übertragung auf dem Bus erfolgt der dritte Aufruf von <code>LinIf_MainFunction</code>.\n</li><li>Das LinIf ruft <code>Lin_GetStatus</code> auf, um den Status der übertragenen Response vom LIN-Treiber abzufragen und das Frame-Timing abzuschließen.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Verdeutlicht das polling-basierte Design des LIN-Interface-Schedulings bei Transmit-Frames.\n</li><li><code>LinIf_MainFunction</code> muss mit einer Periodendauer (Tick-Rate) aufgerufen werden, die feingranular genug ist, um das Frame-Timing und die Statusabfragen abzubilden.\n</li><li>Entwickler müssen beachten, dass das LIN-Interface bei Übertragungen, die sich über mehrere Ticks erstrecken, Zwischenaufrufe ohne Bus-/Treiberaktionen durchläuft, bis das erwartete Übertragungsende erreicht ist und der Status via <code>Lin_GetStatus</code> verifiziert wird.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-fffa62ee09fd2e4f", "to": "FIG-7e78571c65300fe4", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-7e78571c65300fe4", "to": "FIG-85747e80641fc41d", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Textbox „First call...“: Abschließender Punkt nach „called.“ ergänzt.\n</li><li>Textbox „Second call...“: Abschließender Punkt nach „action.“ ergänzt.\n</li><li>Textbox „Third call...“: Abschließender Punkt nach „response.“ ergänzt.\n</li></ul>"}]};
